/// <summary>
///
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    super(_entityCtx, _dataSourceCtx);

    switch (_dataSourceCtx.name())
    {
        case tableStr(METSiteControllingAndSubOrdinateSetup):
            if (_dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert
                || _dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
            {
                METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup = _dataSourceCtx.getBuffer();
                metSiteControllingAndSubOrdinateSetup.State = metSiteControllingAndSubOrdinateSetup.getStateForInventSitePrimaryAddress();
            }
            break;
    }
}

/// <summary>
/// Get primary state for the Site
/// </summary>
public static str getPrimaryStateForSite()
{
    str state;

    str siteId = SysComputedColumn::returnField(tablestr(METSiteControllingAndSubordinateSetupEntity),
                                                dataEntityDataSourceStr(METSiteControllingAndSubordinateSetupEntity, METSiteControllingAndSubOrdinateSetup),
                                                fieldstr(METSiteControllingAndSubOrdinateSetup, SiteId));


    state = strFmt(@"SELECT TOP 1 Addr.STATE
                    FROM LOGISTICSPOSTALADDRESS AS Addr
                    INNER JOIN LOGISTICSLOCATION AS Loc ON Addr.LOCATION = Loc.RECID
                    INNER JOIN INVENTSITELOGISTICSLOCATION AS SiteLoc ON Loc.RECID = SiteLoc.LOCATION
                    INNER JOIN INVENTSITE AS Site ON SiteLoc.SITE = Site.RECID
                    WHERE SiteLoc.ISPRIMARY = 1
                      AND Site.SITEID = %1
                            ", siteId);

    return state;
}
